"""Provider notification adapter for the billing service.

Implements the v1 wire format described in ``docs/provider-notifications.md``.
Everything returned from :func:`parse_payment` is handed to the account-crediting
worker, so a notification is only accepted once its body has been authenticated
against the shared secret.
"""

import hashlib
import hmac
import json
import math
import re

from payhook.errors import InvalidNotification

TIMESTAMP_HEADER = "x-pay-timestamp"
SIGNATURE_HEADER = "x-pay-signature"

_SIGNATURE_SCHEME = "v1="

# Deliveries are accepted when the timestamp is within this many seconds of
# ``now``, in either direction.
_MAX_CLOCK_SKEW_SECONDS = 300

# A decimal Unix timestamp: digits with an optional sign and optional fraction.
# Exponent notation, "inf" and "nan" are deliberately excluded.
_TIMESTAMP_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?\Z")
_CURRENCY_RE = re.compile(r"[A-Z]{3}\Z")
_HEX_RE = re.compile(r"[0-9a-fA-F]+\Z")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    Raises :class:`payhook.errors.InvalidNotification` when the notification
    cannot be accepted: a missing or malformed header, a stale timestamp, an
    unauthenticated body, malformed JSON, or a malformed payment field.
    """
    body = _as_body_bytes(raw_body)
    key = _as_secret_bytes(secret)

    # 1. The timestamp is public and not secret-dependent, so it is validated
    #    first to reject stale and malformed deliveries cheaply.
    stamp = _require_header(headers, TIMESTAMP_HEADER)
    timestamp = _parse_timestamp(stamp)
    _reject_if_out_of_window(timestamp, now)

    # 2. Authenticate the exact received body before looking at its contents.
    signature = _require_header(headers, SIGNATURE_HEADER)
    _verify_v1_signature(key, stamp, body, signature)

    # 3. Only now is the body trusted enough to parse and normalize.
    return _normalize(_parse_json(body))


def _as_body_bytes(raw_body):
    if isinstance(raw_body, bytes):
        return raw_body
    if isinstance(raw_body, (bytearray, memoryview)):
        return bytes(raw_body)
    if isinstance(raw_body, str):
        return raw_body.encode("utf-8")
    raise InvalidNotification("request body must be bytes")


def _as_secret_bytes(secret):
    if isinstance(secret, bytes):
        return secret
    if isinstance(secret, (bytearray, memoryview)):
        return bytes(secret)
    if isinstance(secret, str):
        return secret.encode("utf-8")
    raise InvalidNotification("secret must be bytes")


def _require_header(headers, name):
    value = _find_header(headers, name)
    if value is None:
        raise InvalidNotification("missing %s header" % name)
    if isinstance(value, bytes):
        try:
            value = value.decode("ascii")
        except UnicodeDecodeError:
            raise InvalidNotification("%s header is not ASCII" % name)
    if not isinstance(value, str):
        raise InvalidNotification("%s header must be a string" % name)
    return value


def _find_header(headers, name):
    """Look a header up case-insensitively.

    HTTP header names are case-insensitive and the public ingress may normalize
    them, so both mappings and iterables of ``(name, value)`` pairs are handled.
    """
    if hasattr(headers, "items"):
        pairs = headers.items()
    else:
        try:
            pairs = list(headers)
        except TypeError:
            raise InvalidNotification("headers must be a mapping or a list of pairs")
    for pair in pairs:
        try:
            key, value = pair
        except (TypeError, ValueError):
            raise InvalidNotification("headers must be a mapping or a list of pairs")
        if isinstance(key, bytes):
            try:
                key = key.decode("ascii")
            except UnicodeDecodeError:
                continue
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _parse_timestamp(stamp):
    if not _TIMESTAMP_RE.match(stamp):
        raise InvalidNotification("X-Pay-Timestamp is not a decimal Unix timestamp")
    try:
        value = float(stamp)
    except (OverflowError, ValueError):
        raise InvalidNotification("X-Pay-Timestamp is out of range")
    if not math.isfinite(value):
        raise InvalidNotification("X-Pay-Timestamp is out of range")
    return value


def _reject_if_out_of_window(timestamp, now):
    try:
        reference = float(now)
    except (TypeError, ValueError):
        raise InvalidNotification("`now` must be a numeric Unix timestamp")
    if not math.isfinite(reference):
        raise InvalidNotification("`now` must be a finite numeric timestamp")
    if abs(timestamp - reference) > _MAX_CLOCK_SKEW_SECONDS:
        raise InvalidNotification("timestamp is outside the accepted window")


def _verify_v1_signature(key, stamp, body, signature):
    """Check the v1 digest over ``timestamp || "." || body`` in constant time."""
    if not signature.startswith(_SIGNATURE_SCHEME):
        raise InvalidNotification("unsupported signature scheme")
    provided = signature[len(_SIGNATURE_SCHEME):]
    if not _HEX_RE.match(provided):
        raise InvalidNotification("signature is not a hex digest")

    # The digest covers the timestamp exactly as received, so the header value
    # is used verbatim rather than any normalized rendering of it.
    signed = stamp.encode("ascii") + b"." + body
    expected = hmac.new(key, signed, hashlib.sha256).hexdigest()

    # compare_digest keeps the check independent of secret-dependent timing.
    if not hmac.compare_digest(provided.lower(), expected):
        raise InvalidNotification("signature does not match the received body")


def _parse_json(body):
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidNotification("body is not valid UTF-8")
    try:
        return json.loads(text)
    except ValueError:
        raise InvalidNotification("body is not valid JSON")
    except RecursionError:
        raise InvalidNotification("body is too deeply nested")


def _normalize(event):
    if not isinstance(event, dict):
        raise InvalidNotification("notification body is not a JSON object")

    return {
        "event_id": _require_text(event, "event_id"),
        "account_id": _require_text(event, "account_id"),
        "amount_minor": _require_amount(event),
        "currency": _require_currency(event),
    }


def _require_text(event, field):
    value = event.get(field)
    if not isinstance(value, str):
        raise InvalidNotification("%s must be a string" % field)
    if not value:
        raise InvalidNotification("%s must not be empty" % field)
    return value


def _require_amount(event):
    amount = event.get("amount_minor")
    # bool is a subclass of int, so booleans are rejected explicitly.
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise InvalidNotification("amount_minor must be an integer")
    if amount < 0:
        raise InvalidNotification("amount_minor must be nonnegative")
    return amount


def _require_currency(event):
    currency = event.get("currency")
    if not isinstance(currency, str) or not _CURRENCY_RE.match(currency):
        raise InvalidNotification("currency must be three uppercase ASCII letters")
    return currency
